/// A data header describing the shared memory layout of a "record" or "row"
/// batch. Some systems call this a "row batch" internally and others a "record
/// batch".
#[derive(Default, PartialEq, Debug, Clone, Hash, Eq, Serialize, Deserialize)]
pub struct RecordBatch {
    /// Buffers correspond to the pre-ordered flattened buffer tree
    ///
    /// The number of buffers appended to this list depends on the schema. For
    /// example, most primitive arrays will have 2 buffers, 1 for the validity
    /// bitmap and 1 for the values. For struct arrays, there will only be a
    /// single buffer for the validity (nulls) bitmap
    pub buffers: Option<Vec<Buffer>>,
    /// Optional compression of the message body
    pub compression: Option<BodyCompression>,
    /// number of records / rows. The arrays in the batch should all have this
    /// length
    pub length: i64,
    /// Nodes correspond to the pre-ordered flattened logical schema
    pub nodes: Option<Vec<FieldNode>>,
    /// Some types such as Utf8View are represented using a variable number of buffers.
    /// For each such Field in the pre-ordered flattened logical schema, there will be
    /// an entry in variadicBufferCounts to indicate the number of number of variadic
    /// buffers which belong to that Field in the current RecordBatch.
    ///
    /// For example, the schema
    /// col1: Struct<alpha: Int32, beta: BinaryView, gamma: Float64>
    /// col2: Utf8View
    /// contains two Fields with variadic buffers so variadicBufferCounts will have
    /// two entries, the first counting the variadic buffers of `col1.beta` and the
    /// second counting `col2`'s.
    ///
    /// This field may be omitted if and only if the schema contains no Fields with
    /// a variable number of buffers, such as BinaryView and Utf8View.
    pub variadicBufferCounts: Option<Vec<i64>>,
}

impl RecordBatch {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsRecordBatch<'a>> {
        use crate::types::generated::Message_generated::RecordBatchBuilder as FbsRecordBatchBuilder;

        let buffers_offset = self.buffers.as_ref().map(|v| {
            let buffers_offset =
                builder.create_vector_from_iter(v.iter().cloned().map(Into::<FbsBuffer>::into));
            buffers_offset
        });
        let compression_offset = self.compression.as_ref().map(|o| o.serialize_to(builder));
        let nodes_offset = self.nodes.as_ref().map(|v| {
            let nodes_offset =
                builder.create_vector_from_iter(v.iter().cloned().map(Into::<FbsFieldNode>::into));
            nodes_offset
        });
        let variadicBufferCounts_offset = self.variadicBufferCounts.as_ref().map(|v| {
            let variadicBufferCounts_offset = builder.create_vector(&v);
            variadicBufferCounts_offset
        });

        let mut bldr = FbsRecordBatchBuilder::new(builder);
        if let Some(offset) = buffers_offset {
            bldr.add_buffers(offset);
        }
        if let Some(offset) = compression_offset {
            bldr.add_compression(offset);
        }
        bldr.add_length(self.length);
        if let Some(offset) = nodes_offset {
            bldr.add_nodes(offset);
        }
        if let Some(offset) = variadicBufferCounts_offset {
            bldr.add_variadicBufferCounts(offset);
        }
        bldr.finish()
    }
}

impl From<FbsRecordBatch<'_>> for RecordBatch {
    fn from(fbs: FbsRecordBatch<'_>) -> Self {
        let buffers = if let Some(val) = fbs.buffers() {
            let mut buffers = Vec::new();
            for elem in val {
                buffers.push(elem.into());
            }

            Some(buffers)
        } else {
            None
        };

        let compression = fbs.compression().map(BodyCompression::from);
        let length = fbs.length();
        let nodes = if let Some(val) = fbs.nodes() {
            let mut nodes = Vec::new();
            for elem in val {
                nodes.push(elem.into());
            }

            Some(nodes)
        } else {
            None
        };

        let variadicBufferCounts = if let Some(val) = fbs.variadicBufferCounts() {
            let mut variadicBufferCounts = Vec::new();
            for elem in val {
                variadicBufferCounts.push(elem.into());
            }

            Some(variadicBufferCounts)
        } else {
            None
        };

        Self {
            buffers,
            compression,
            length,
            nodes,
            variadicBufferCounts,
        }
    }
}

