/// ----------------------------------------------------------------------
/// The root Message type
/// This union enables us to easily send different message types without
/// redundant storage, and in the future we can easily add new message types.
///
/// Arrow implementations do not need to implement all of the message types,
/// which may include experimental metadata types. For maximum compatibility,
/// it is best to send data using RecordBatch
#[derive(Clone, Debug, PartialEq, Hash, Eq, Serialize, Deserialize)]
pub enum MessageHeader {
    Schema(Schema),
    DictionaryBatch(DictionaryBatch),
    RecordBatch(RecordBatch),
    Tensor(Tensor),
    SparseTensor(SparseTensor),
}

impl Default for MessageHeader {
    fn default() -> Self {
        Self::Schema(Schema::default())
    }
}

impl MessageHeader {
    pub fn serialize_to(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder,
    ) -> (WIPOffset<UnionWIPOffset>, FbsMessageHeader) {
        match self {
            Self::Schema(val) => {
                let offset = val.serialize_to(builder).as_union_value();
                let ty = FbsMessageHeader::Schema;
                (offset, ty)
            }
            Self::DictionaryBatch(val) => {
                let offset = val.serialize_to(builder).as_union_value();
                let ty = FbsMessageHeader::DictionaryBatch;
                (offset, ty)
            }
            Self::RecordBatch(val) => {
                let offset = val.serialize_to(builder).as_union_value();
                let ty = FbsMessageHeader::RecordBatch;
                (offset, ty)
            }
            Self::Tensor(val) => {
                let offset = val.serialize_to(builder).as_union_value();
                let ty = FbsMessageHeader::Tensor;
                (offset, ty)
            }
            Self::SparseTensor(val) => {
                let offset = val.serialize_to(builder).as_union_value();
                let ty = FbsMessageHeader::SparseTensor;
                (offset, ty)
            }
        }
    }
}

/// ----------------------------------------------------------------------
/// Data structures for describing a table row batch (a collection of
/// equal-length Arrow arrays)
/// Metadata about a field at some level of a nested type tree (but not
/// its children).
///
/// For example, a List<Int16> with values `[[1, 2, 3], null, [4], [5, 6], null]`
/// would have {length: 5, null_count: 2} for its List node, and {length: 6,
/// null_count: 0} for its Int16 node, as separate FieldNode structs
#[derive(Default, PartialEq, Debug, Clone, Hash, Eq, Serialize, Deserialize)]
pub struct FieldNode {
    /// The number of value slots in the Arrow array at this level of a nested
    /// tree
    pub length: i64,
    /// The number of observed nulls. Fields with null_count == 0 may choose not
    /// to write their physical validity bitmap out as a materialized buffer,
    /// instead setting the length of the bitmap buffer to 0.
    pub null_count: i64,
}

impl From<FieldNode> for FbsFieldNode {
    fn from(obj: FieldNode) -> Self {
        let length = obj.length;
        let null_count = obj.null_count;

        Self::new(length, null_count)
    }
}

impl From<&FbsFieldNode> for FieldNode {
    fn from(fbs: &FbsFieldNode) -> Self {
        Self {
            length: fbs.length(),
            null_count: fbs.null_count(),
        }
    }
}

#[derive(Default, PartialEq, Debug, Clone, Hash, Eq, Serialize, Deserialize)]
pub struct Message {
    pub bodyLength: i64,
    pub custom_metadata: Option<Vec<KeyValue>>,
    pub header: Option<MessageHeader>,
    pub version: MetadataVersion,
}

impl Message {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsMessage<'a>> {
        use crate::types::generated::Message_generated::MessageBuilder as FbsMessageBuilder;

        let custom_metadata_offset = self.custom_metadata.as_ref().map(|v| {
            let mut custom_metadata_offsets = Vec::with_capacity(v.len());
            for val in v.iter() {
                let offset = val.serialize_to(builder);
                custom_metadata_offsets.push(offset);
            }
            let custom_metadata_offset = builder.create_vector(&custom_metadata_offsets);
            custom_metadata_offset
        });
        let header_offset = self.header.as_ref().map(|u| u.serialize_to(builder));

        let mut bldr = FbsMessageBuilder::new(builder);
        bldr.add_bodyLength(self.bodyLength);
        if let Some(offset) = custom_metadata_offset {
            bldr.add_custom_metadata(offset);
        }
        if let Some((offset, ty)) = header_offset {
            bldr.add_header(offset);
            bldr.add_header_type(ty);
        }
        bldr.add_version(FbsMetadataVersion::from(self.version));
        bldr.finish()
    }
}

impl From<FbsMessage<'_>> for Message {
    fn from(fbs: FbsMessage<'_>) -> Self {
        let bodyLength = fbs.bodyLength();
        let custom_metadata = if let Some(val) = fbs.custom_metadata() {
            let mut custom_metadata = Vec::new();
            for elem in val {
                custom_metadata.push(elem.into());
            }

            Some(custom_metadata)
        } else {
            None
        };

        let header = if let Some(val) = fbs.header() {
            let header = match fbs.header_type() {
                FbsMessageHeader::Schema => {
                    MessageHeader::Schema(Schema::from(fbs.header_as_schema().unwrap()))
                }
                FbsMessageHeader::DictionaryBatch => MessageHeader::DictionaryBatch(
                    DictionaryBatch::from(fbs.header_as_dictionary_batch().unwrap()),
                ),
                FbsMessageHeader::RecordBatch => MessageHeader::RecordBatch(RecordBatch::from(
                    fbs.header_as_record_batch().unwrap(),
                )),
                FbsMessageHeader::Tensor => {
                    MessageHeader::Tensor(Tensor::from(fbs.header_as_tensor().unwrap()))
                }
                FbsMessageHeader::SparseTensor => MessageHeader::SparseTensor(SparseTensor::from(
                    fbs.header_as_sparse_tensor().unwrap(),
                )),
                _ => unreachable!(),
            };

            Some(header)
        } else {
            None
        };

        let version = MetadataVersion::from(fbs.version());
        Self {
            bodyLength,
            custom_metadata,
            header,
            version,
        }
    }
}

impl crate::FbsSerde for Message {
    fn to_fbs_bytes(&self) -> Vec<u8> {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = self.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }

    fn from_fbs_bytes(bytes: &[u8]) -> Result<Self, flatbuffers::InvalidFlatbuffer> {
        let opts = flatbuffers::VerifierOptions {
            max_tables: 100_000_000,
            ..Default::default()
        };
        let fbs = flatbuffers::size_prefixed_root_with_opts::<FbsMessage>(&opts, bytes)?;
        Ok(Self::from(fbs))
    }
}

